  1 | /**
  2 |  * Audio cache using IndexedDB for offline playback and faster loading.
  3 |  * Caches audio blobs keyed by track ID or source URL.
  4 |  * Max cache size: ~200MB by default.
  5 |  */
  6 | 
  7 | const DB_NAME = "llama-player-audio-cache";
  8 | const DB_VERSION = 1;
  9 | const STORE_NAME = "audio-blobs";
 10 | const META_STORE = "cache-meta";
 11 | 
 12 | interface CacheMeta {
 13 |   key: string;
 14 |   size: number; // bytes
 15 |   cachedAt: number;
 16 |   trackTitle: string;
 17 |   mimeType: string;
 18 | }
 19 | 
 20 | const DEFAULT_MAX_SIZE = 200 * 1024 * 1024; // 200MB
 21 | 
 22 | let dbInstance: IDBDatabase | null = null;
 23 | 
 24 | function openDB(): Promise<IDBDatabase> {
 25 |   if (dbInstance) return Promise.resolve(dbInstance);
 26 | 
 27 |   return new Promise((resolve, reject) => {
 28 |     const request = indexedDB.open(DB_NAME, DB_VERSION);
 29 | 
 30 |     request.onupgradeneeded = (event) => {
 31 |       const db = (event.target as IDBOpenDBRequest).result;
 32 | 
 33 |       if (!db.objectStoreNames.contains(STORE_NAME)) {
 34 |         const store = db.createObjectStore(STORE_NAME, { keyPath: "key" });
 35 |         store.createIndex("cachedAt", "cachedAt", { unique: false });
 36 |       }
 37 | 
 38 |       if (!db.objectStoreNames.contains(META_STORE)) {
 39 |         const metaStore = db.createObjectStore(META_STORE, { keyPath: "key" });
 40 |         metaStore.createIndex("cachedAt", "cachedAt", { unique: false });
 41 |         metaStore.createIndex("size", "size", { unique: false });
 42 |       }
 43 |     };
 44 | 
 45 |     request.onsuccess = (event) => {
 46 |       dbInstance = (event.target as IDBOpenDBRequest).result;
 47 |       resolve(dbInstance!);
 48 |     };
 49 | 
 50 |     request.onerror = (event) => {
 51 |       console.warn("[Llama Player] IndexedDB error:", (event.target as IDBOpenDBRequest).error);
 52 |       reject((event.target as IDBOpenDBRequest).error);
 53 |     };
 54 |   });
 55 | }
