 57 | async function getTotalCacheSize(): Promise<number> {
 58 |   try {
 59 |     const db = await openDB();
 60 |     const tx = db.transaction(META_STORE, "readonly");
 61 |     const store = tx.objectStore(META_STORE);
 62 |     const allMeta = await new Promise<CacheMeta[]>((resolve, reject) => {
 63 |       const request = store.getAll();
 64 |       request.onsuccess = () => resolve(request.result);
 65 |       request.onerror = () => reject(request.error);
 66 |     });
 67 |     return allMeta.reduce((sum, meta) => sum + meta.size, 0);
 68 |   } catch {
 69 |     return 0;
 70 |   }
 71 | }
 72 | 
 73 | async function evictOldest(requiredSpace: number): Promise<void> {
 74 |   try {
 75 |     const db = await openDB();
 76 |     const tx = db.transaction([META_STORE, STORE_NAME], "readwrite");
 77 |     const metaStore = tx.objectStore(META_STORE);
 78 |     const blobStore = tx.objectStore(STORE_NAME);
 79 | 
 80 |     const allMeta = await new Promise<CacheMeta[]>((resolve, reject) => {
 81 |       const request = metaStore.index("cachedAt").getAll();
 82 |       request.onsuccess = () => resolve(request.result);
 83 |       request.onerror = () => reject(request.error);
 84 |     });
 85 | 
 86 |     // Sort oldest first
 87 |     allMeta.sort((a, b) => a.cachedAt - b.cachedAt);
 88 | 
 89 |     let freed = 0;
 90 |     for (const meta of allMeta) {
 91 |       if (freed >= requiredSpace) break;
 92 |       blobStore.delete(meta.key);
 93 |       metaStore.delete(meta.key);
 94 |       freed += meta.size;
 95 |     }
 96 |   } catch (err) {
 97 |     console.warn("[Llama Player] Error evicting cache:", err);
 98 |   }
 99 | }
