101 | export async function cacheAudioBlob(
102 |   key: string,
103 |   blob: Blob,
104 |   trackTitle: string
105 | ): Promise<void> {
106 |   try {
107 |     const db = await openDB();
108 | 
109 |     // Check if we need to evict
110 |     const totalSize = await getTotalCacheSize();
111 |     const blobSize = blob.size;
112 |     const maxSize = DEFAULT_MAX_SIZE;
113 | 
114 |     if (totalSize + blobSize > maxSize) {
115 |       await evictOldest(totalSize + blobSize - maxSize);
116 |     }
117 | 
118 |     const tx = db.transaction([STORE_NAME, META_STORE], "readwrite");
119 |     const blobStore = tx.objectStore(STORE_NAME);
120 |     const metaStore = tx.objectStore(META_STORE);
121 | 
122 |     const now = Date.now();
123 | 
124 |     blobStore.put({ key, blob, cachedAt: now });
125 | 
126 |     const meta: CacheMeta = {
127 |       key,
128 |       size: blobSize,
129 |       cachedAt: now,
130 |       trackTitle,
131 |       mimeType: blob.type || "audio/mpeg",
132 |     };
133 |     metaStore.put(meta);
134 |   } catch (err) {
135 |     console.warn("[Llama Player] Error caching audio:", err);
136 |   }
137 | }
