139 | export async function getCachedAudio(key: string): Promise<Blob | null> {
140 |   try {
141 |     const db = await openDB();
142 |     const tx = db.transaction(STORE_NAME, "readonly");
143 |     const store = tx.objectStore(STORE_NAME);
144 | 
145 |     const result = await new Promise<{ key: string; blob: Blob; cachedAt: number } | undefined>(
146 |       (resolve, reject) => {
147 |         const request = store.get(key);
148 |         request.onsuccess = () => resolve(request.result);
149 |         request.onerror = () => reject(request.error);
150 |       }
151 |     );
152 | 
153 |     return result?.blob ?? null;
154 |   } catch {
155 |     return null;
156 |   }
157 | }
