160 |   try {
161 |     const db = await openDB();
162 |     const tx = db.transaction(META_STORE, "readonly");
163 |     const store = tx.objectStore(META_STORE);
164 | 
165 |     const result = await new Promise<CacheMeta | undefined>((resolve, reject) => {
166 |       const request = store.get(key);
167 |       request.onsuccess = () => resolve(request.result);
168 |       request.onerror = () => reject(request.error);
169 |     });
170 | 
171 |     return result ?? null;
172 |   } catch {
