177 | export async function removeCachedAudio(key: string): Promise<void> {
178 |   try {
179 |     const db = await openDB();
180 |     const tx = db.transaction([STORE_NAME, META_STORE], "readwrite");
181 |     tx.objectStore(STORE_NAME).delete(key);
182 |     tx.objectStore(META_STORE).delete(key);
183 |   } catch {
184 |     // ignore
185 |   }
186 | }
