188 | export async function clearAudioCache(): Promise<void> {
189 |   try {
190 |     const db = await openDB();
191 |     const tx = db.transaction([STORE_NAME, META_STORE], "readwrite");
192 |     tx.objectStore(STORE_NAME).clear();
193 |     tx.objectStore(META_STORE).clear();
194 |   } catch {
195 |     // ignore
196 |   }
197 | }
