199 | export async function getCacheStats(): Promise<{
200 |   count: number;
201 |   totalSize: number;
202 |   maxSize: number;
203 | }> {
204 |   try {
205 |     const db = await openDB();
206 |     const tx = db.transaction(META_STORE, "readonly");
207 |     const store = tx.objectStore(META_STORE);
208 |     const allMeta = await new Promise<CacheMeta[]>((resolve, reject) => {
209 |       const request = store.getAll();
210 |       request.onsuccess = () => resolve(request.result);
211 |       request.onerror = () => reject(request.error);
212 |     });
213 | 
214 |     return {
215 |       count: allMeta.length,
216 |       totalSize: allMeta.reduce((sum, m) => sum + m.size, 0),
217 |       maxSize: DEFAULT_MAX_SIZE,
218 |     };
219 |   } catch {
220 |     return { count: 0, totalSize: 0, maxSize: DEFAULT_MAX_SIZE };
221 |   }
222 | }
