224 | export function formatCacheSize(bytes: number): string {
225 |   if (bytes < 1024) return `${bytes} B`;
226 |   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
227 |   return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
228 | }
